class Files:
    def __init__(self): self.files = {}
    def write(self, name, data): self.files[name] = bytes(data)
    def read(self, name): return self.files.get(name)
    def list(self, prefix): return [name for name in self.files if name.startswith(prefix)]
    def delete(self, name): self.files.pop(name, None)
files = Files(); store = BasicKVStore(files)
for key, value in [('', ''), ('a\nb', 'x\x00y'), ('键', '值')]: store.set(key, value)
store.snapshot(); restored = BasicKVStore(files); assert restored.restore() is True
assert [restored.get(key) for key in ['', 'a\nb', '键']] == ['', 'x\x00y', '值']

class Files:
    def __init__(self): self.files = {}
    def write(self, name, data): self.files[name] = bytes(data)
    def read(self, name): return self.files.get(name)
    def list(self, prefix): return [name for name in self.files if name.startswith(prefix)]
    def delete(self, name): self.files.pop(name, None)
files = Files(); store = ChunkedKVStore(files, prefix='state', chunk_size=13)
store.set('first', 'x' * 40); store.snapshot(); old_names = set(files.list('state.'))
store.set('first', 'new'); store.set('second', 'more'); store.snapshot()
assert all(len(data) <= 13 for name, data in files.files.items() if name.startswith('state.') and name != 'state.manifest')
files.write('state.orphan.0', b'not a committed snapshot')
restored = ChunkedKVStore(files, prefix='state', chunk_size=13); assert restored.restore() is True
assert restored.get('first') == 'new' and restored.get('second') == 'more'
assert old_names - set(files.list('state.')) or old_names

class Files:
    def __init__(self): self.files = {}
