files = Files(); files.write('snapshot.bin', b'\x00\x00\x00\x05ab')
store = BasicKVStore(files); store.set('safe', 'value')
try:
    store.restore(); assert False
except ValueError: pass
assert store.get('safe') == 'value'
assert ChunkedKVStore(files, prefix='missing').restore() is False
